import{_ as e,c as r,o as t,ah as o}from"./chunks/framework.l36K22_3.js";const P=JSON.parse('{"title":"如何撰写PRD文档","description":"","frontmatter":{"title":"如何撰写PRD文档"},"headers":[],"relativePath":"knowledge/study/prd-document.md","filePath":"knowledge/study/prd-document.md","lastUpdated":1788862678000}'),d={name:"knowledge/study/prd-document.md"};function n(i,a,l,s,h,p){return t(),r("div",null,a[0]||(a[0]=[o('<p>产品经理主要有两项职责：</p><ol><li>评估产品机会</li><li>定义要开发的产品；</li></ol><p>定义开发的产品则需要通过产品需求文档(PRD)来描述产品的特征和功能。</p><h2 id="prd-开发需求文档-的作用" tabindex="-1">PRD(开发需求文档）的作用 <a class="header-anchor" href="#prd-开发需求文档-的作用" aria-label="Permalink to &quot;PRD(开发需求文档）的作用&quot;">​</a></h2><p>在学习如何撰写 PRD 之前，我们先要明白写 PRD 的目的是什么：</p><h3 id="_1-概念化-阶段进入到-图纸化" tabindex="-1">① <strong>概念化”阶段进入到“图纸化”</strong> <a class="header-anchor" href="#_1-概念化-阶段进入到-图纸化" aria-label="Permalink to &quot;① **概念化”阶段进入到“图纸化”**&quot;">​</a></h3><p>我们之前在市场需求文档（MRD）中阐述到的功能，都是表达的一个意向，不考虑实现方法和细节。而 PRD 则是将概念图纸化，需要阐述详细的细节和实现模型。产品人员可以通过撰写 PRD，梳理清楚方案实现过程中的各种问题和影响。</p><h3 id="_2-向项目成员传达需求的意义和明细" tabindex="-1">② <strong>向项目成员传达需求的意义和明细</strong> <a class="header-anchor" href="#_2-向项目成员传达需求的意义和明细" aria-label="Permalink to &quot;② **向项目成员传达需求的意义和明细**&quot;">​</a></h3><p>PRD 的主要面向对象是项目经理、开发、设计和测试。如何向这些不同的角色表达清楚需求明细，就需要一份规范的 PRD 文档来描述。项目经理通过文档可以迅速了解任务的规模和相关接口，而开发设计人员通过文档可以了解页面元素和用例规则，测试人员可以提前根据文档撰写测试用例。PRD 文档在形式上是项目启动的必要元素之一。</p><h3 id="_3-管理归档需求" tabindex="-1">③ <strong>管理归档需求</strong> <a class="header-anchor" href="#_3-管理归档需求" aria-label="Permalink to &quot;③ **管理归档需求**&quot;">​</a></h3><p>大都数的新需求都需要迭代几个版本后才能走向成熟稳定的阶段，如果没有 PRD 文档，在大型项目中，需求的迭代变更将变的无据可循。PRD 的文档修订编号和命名也是项目规范化管理的主要方法之一。</p><h2 id="prd-的表现形式" tabindex="-1">PRD 的表现形式 <a class="header-anchor" href="#prd-的表现形式" aria-label="Permalink to &quot;PRD 的表现形式&quot;">​</a></h2><p>一般企业内部的 PRD 文档选择 wiki 系统或 word 文档。wiki 在协同和保密方面会有优势，而且能够记录修改文档的每一次变更。而 word 在阅读修改方面比较有优势，一般使用 Word 加 SVN 的方式来管理更新文档。这个可根据每个企业的管理规范来选择那种方法更合适。</p><h2 id="prd-的主要构成" tabindex="-1">PRD 的主要构成 <a class="header-anchor" href="#prd-的主要构成" aria-label="Permalink to &quot;PRD 的主要构成&quot;">​</a></h2><p>一份基础的 PRD 文档主要由三部分组成</p><h3 id="_1-引言" tabindex="-1">① <strong>引言</strong> <a class="header-anchor" href="#_1-引言" aria-label="Permalink to &quot;① **引言**&quot;">​</a></h3><p>引言部分主要包括：需求背景、需求目的、需求概要、涉及范围、全局规则和名词说明，交互原型地址等。引言部分的写作目的是让阅读者快速理解需求背景和概要。如果是公司内部文档，引言部分可以从简写作。</p><h3 id="_2-业务建模" tabindex="-1">② <strong>业务建模</strong> <a class="header-anchor" href="#_2-业务建模" aria-label="Permalink to &quot;② **业务建模**&quot;">​</a></h3><p>建模的目的是为了帮助阅读对象更好的理解需要开发的需求，常用的模型种类包括：用例图、实体图、状态图、流程图等。常用的建模语言如 UML。</p><h3 id="_3-业务模块" tabindex="-1">③ <strong>业务模块</strong> <a class="header-anchor" href="#_3-业务模块" aria-label="Permalink to &quot;③ **业务模块**&quot;">​</a></h3><p>业务模块包含具体页面的元素、用例规则，以及相关的原型，流程图。业务模块的描述是整个文档最核心的部分，下面博主用案例来描述一下业务模块的编写方法。</p><br>',22)]))}const _=e(d,[["render",n]]);export{P as __pageData,_ as default};
